default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\Securepipeservers\Winreg\AllowedExactpaths' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('Machine', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [string[]] -and $current.Length -eq 3 -and [string]::Join([string][char]0, $current) -ceq [string]::Join([string][char]0, @('System\CurrentControlSet\Control\ProductOptions', 'System\CurrentControlSet\Control\Server Applications', 'Software\Microsoft\Windows NT\CurrentVersion')))) {
    Write-Output 'Mismatch: HKLM:\SYSTEM\CurrentControlSet\Control\Securepipeservers\Winreg\AllowedExactpaths [Machine]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\Securepipeservers\Winreg\AllowedExactpaths')) {
    New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Securepipeservers\Winreg\AllowedExactpaths' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\Securepipeservers\Winreg\AllowedExactpaths' -Name 'Machine' -Value @('System\CurrentControlSet\Control\ProductOptions', 'System\CurrentControlSet\Control\Server Applications', 'Software\Microsoft\Windows NT\CurrentVersion') -PropertyType MultiString -Force | Out-Null
exit 0
